"""Tiny in-memory cache with TTL support."""


class Cache:
    def __init__(self, ttl=60):
        self._store = {}
        self._ttl = ttl

    def set(self, key, value):
        self._store[key] = (value, time.time() + self._ttl)

    def get(self, key):
        value, timestamp = self._store.get(key)
        if timestamp and timestamp < time.time():
            del self._store[key]
            return None
        return value
```

